package com.passiongo.repartidores;

import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Native Android client. Firebase ID tokens are kept in memory only. */
public class MainActivity extends Activity {
  static final String KEY="AIzaSyAbVoKH_VR2bjfNzOdGvkZJkTLZULvLMpM";
  static final String BASE="https://firestore.googleapis.com/v1/projects/erp-passion/databases/(default)/documents";
  final ExecutorService executor=Executors.newSingleThreadExecutor();
  final int navy=Color.rgb(8,40,91), orange=Color.rgb(245,111,25), muted=Color.rgb(100,116,139);
  LinearLayout screen, orders;
  TextView message;
  EditText email,password;
  String token="", uid="", driverId="", driverName="", sede="";
  long expiresAt=0;
  boolean busy=false;
  final List<String> zones=new ArrayList<>();
  int generation=0;

  @Override public void onCreate(Bundle state){ super.onCreate(state); getWindow().setStatusBarColor(navy); getWindow().setNavigationBarColor(Color.WHITE); login(); }
  int dp(int n){return (int)(getResources().getDisplayMetrics().density*n);}
  LinearLayout column(){ LinearLayout v=new LinearLayout(this); v.setOrientation(LinearLayout.VERTICAL); return v; }
  void base(){ screen=column(); screen.setPadding(dp(20),dp(28),dp(20),dp(24)); screen.setBackgroundColor(Color.rgb(245,247,251)); ScrollView scroll=new ScrollView(this); scroll.setFillViewport(true); scroll.addView(screen); setContentView(scroll); }
  TextView text(LinearLayout parent,String label,int size,int color){TextView v=new TextView(this);v.setText(label);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(6),0,dp(8));parent.addView(v);return v;}
  Button button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(navy));parent.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->action.run());return b;}
  void brand(){ImageView icon=new ImageView(this);icon.setImageResource(getResources().getIdentifier("app_icon","drawable",getPackageName()));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);screen.addView(icon,new LinearLayout.LayoutParams(-1,dp(106)));text(screen,"Passion Go",30,navy).setTypeface(null,Typeface.BOLD);text(screen,"REPARTIDORES · ÚLTIMA MILLA",12,orange);}
  void login(){generation++;token="";uid="";zones.clear();base();brand();text(screen,"Tu ruta empieza aquí",23,navy);text(screen,"Accede con la cuenta de repartidor registrada por tu administrador.",14,muted);email=new EditText(this);email.setHint("Correo electrónico");email.setInputType(33);screen.addView(email);password=new EditText(this);password.setHint("Contraseña");password.setInputType(129);screen.addView(password);message=text(screen,"",14,muted);button(screen,"Iniciar sesión",()->signIn());text(screen,"Solo repartidores autorizados. Las zonas se configuran desde el ERP.",12,muted);}
  void error(Exception e){String msg=e.getMessage();runOnUiThread(()->{busy=false;if(message!=null){message.setText(msg==null?"No fue posible conectar. Intenta nuevamente.":msg);message.setTextColor(Color.rgb(185,28,28));}});}
  void signIn(){if(busy)return;final String mail=email.getText().toString().trim(),pass=password.getText().toString();if(mail.isEmpty()||pass.isEmpty()){message.setText("Completa correo y contraseña.");return;}busy=true;message.setText("Verificando acceso…");final int session=generation;executor.execute(()->{try{JSONObject auth=new JSONObject(request("POST","https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key="+KEY,new JSONObject().put("email",mail).put("password",pass).put("returnSecureToken",true).toString(),false));if(session!=generation)return;token=auth.getString("idToken");uid=auth.getString("localId");expiresAt=System.currentTimeMillis()+3300000;JSONObject profile=new JSONObject(request("GET",BASE+"/users/"+uid,null,true)).getJSONObject("fields");if(!"Repartidor".equals(value(profile,"role")))throw new Exception("Esta app es exclusiva para repartidores. Solicita acceso al administrador.");driverId=value(profile,"driverId");if(driverId.isEmpty())throw new Exception("Tu cuenta no tiene un repartidor vinculado. Contacta al administrador.");loadAssignment();if(session==generation)runOnUiThread(()->{busy=false;dashboard();refresh();});}catch(Exception e){token="";error(e);}});}
  String value(JSONObject fields,String name){JSONObject f=fields.optJSONObject(name);return f==null?"":f.optString("stringValue","");}
  void loadAssignment() throws Exception {JSONObject account=new JSONObject(request("GET",BASE+"/users/"+uid,null,true)).getJSONObject("fields");if(!"Repartidor".equals(value(account,"role")))throw new Exception("Tu cuenta ya no tiene acceso de repartidor.");driverId=value(account,"driverId");if(driverId.isEmpty())throw new Exception("Tu cuenta no tiene repartidor vinculado.");JSONObject fields=new JSONObject(request("GET",BASE+"/delivery_drivers/"+Uri.encode(driverId),null,true)).getJSONObject("fields");if("inactive".equals(value(fields,"status")))throw new Exception("Tu perfil está inactivo. Contacta al administrador.");driverName=value(fields,"name");sede=value(fields,"assignedSede");zones.clear();JSONObject a=fields.optJSONObject("assignedZones");JSONArray list=a==null?new JSONArray():a.optJSONArray("values");if(list!=null)for(int i=0;i<list.length();i++){String zone=list.getJSONObject(i).optString("stringValue","");if(!zone.trim().isEmpty())zones.add(zone);}if(sede.isEmpty())throw new Exception("No tienes una sucursal configurada.");}
  void dashboard(){base();brand();text(screen,"Hola, "+driverName,23,navy).setTypeface(null,Typeface.BOLD);text(screen,sede+" · "+String.join(" · ",zones),13,muted);message=text(screen,"",14,muted);button(screen,"Actualizar órdenes",()->refresh());button(screen,"Cerrar sesión",()->{busy=false;login();});orders=column();screen.addView(orders);}
  void refresh(){if(busy)return;if(System.currentTimeMillis()>expiresAt){login();message.setText("La sesión expiró. Inicia sesión nuevamente.");return;}busy=true;final int session=generation;orders.removeAllViews();message.setText("Consultando tus zonas…");executor.execute(()->{try{loadAssignment();Map<String,JSONObject> docs=new LinkedHashMap<>();for(String zone:new ArrayList<>(zones)){JSONObject filter=new JSONObject().put("compositeFilter",new JSONObject().put("op","AND").put("filters",new JSONArray().put(eq("sede",sede)).put(eq("zona",zone))));JSONObject q=new JSONObject().put("from",new JSONArray().put(new JSONObject().put("collectionId","packages"))).put("where",filter);JSONArray response=new JSONArray(request("POST",BASE+":runQuery",new JSONObject().put("structuredQuery",q).toString(),true));for(int i=0;i<response.length();i++){JSONObject d=response.getJSONObject(i).optJSONObject("document");if(d!=null)docs.put(d.getString("name"),d.getJSONObject("fields"));}}if(session==generation)runOnUiThread(()->{busy=false;orders.removeAllViews();message.setText(zones.isEmpty()?"Sin zonas asignadas. Solicita configuración al administrador.":docs.size()+" órdenes en tus zonas · Actualizado ahora");for(JSONObject fields:docs.values())card(fields);if(docs.isEmpty())text(orders,"No hay órdenes disponibles en tus zonas.",16,muted);});}catch(Exception e){if(session==generation)error(e);}});}
  JSONObject eq(String field,String val)throws Exception{return new JSONObject().put("fieldFilter",new JSONObject().put("field",new JSONObject().put("fieldPath",field)).put("op","EQUAL").put("value",new JSONObject().put("stringValue",val)));}
  void card(JSONObject f){LinearLayout c=column();c.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(16));bg.setStroke(dp(1),Color.rgb(225,231,239));c.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(14);orders.addView(c,p);text(c,value(f,"cod")+" · "+value(f,"estado"),13,orange).setTypeface(null,Typeface.BOLD);text(c,value(f,"cliente"),21,navy);text(c,value(f,"zona")+" · "+value(f,"tienda"),13,muted);String note=value(f,"nota");if(!note.isEmpty())text(c,note,14,muted);String phone=value(f,"telefono").replaceAll("[^0-9+]","");if(!phone.isEmpty()){button(c,"Llamar al cliente",()->open("tel:"+phone));button(c,"WhatsApp",()->open("https://wa.me/"+phone.replace("+","")));}button(c,"Ver zona en mapa",()->open("geo:0,0?q="+Uri.encode(value(f,"zona")+", "+sede+", República Dominicana")));}
  void open(String uri){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(uri)));}catch(Exception e){Toast.makeText(this,"No hay una aplicación disponible para esta acción.",Toast.LENGTH_LONG).show();}}
  String request(String method,String address,String body,boolean authenticated)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestMethod(method);if(authenticated)c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json");try{if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.getBytes("UTF-8"));}}int code=c.getResponseCode();InputStream stream=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);}String result=bytes.toString("UTF-8");if(code>=400){if(code==401)throw new Exception("Sesión no válida. Vuelve a iniciar sesión.");if(code==403)throw new Exception("Acceso denegado. El administrador debe publicar las reglas y revisar tu rol y zonas.");if(result.contains("INVALID_LOGIN_CREDENTIALS")||result.contains("INVALID_PASSWORD")||result.contains("EMAIL_NOT_FOUND"))throw new Exception("Correo o contraseña incorrectos.");if(result.contains("OPERATION_NOT_ALLOWED"))throw new Exception("Habilita Correo/contraseña en Firebase Authentication.");if(code==404)throw new Exception("Perfil no encontrado. Solicita al administrador vincular tu cuenta de repartidor.");throw new Exception("No se pudo completar la operación ("+code+"). Intenta nuevamente.");}return result;}finally{c.disconnect();}}
  @Override protected void onDestroy(){generation++;executor.shutdownNow();super.onDestroy();}
}
